package ca.brtalgo.uberwatcher;
import android.accessibilityservice.*;import android.graphics.Path;import android.os.*;import android.view.accessibility.*;import java.util.*;
public class UberAccessibilityService extends AccessibilityService{private final Handler h=new Handler(Looper.getMainLooper());private String last="";private final Runnable loop=new Runnable(){public void run(){scan(true);h.postDelayed(this,30000);}};protected void onServiceConnected(){h.post(loop);}public void onAccessibilityEvent(AccessibilityEvent e){if(e==null||e.getPackageName()==null)return;String p=e.getPackageName().toString().toLowerCase(Locale.US);if(p.equals("com.ubercab.driver")||p.startsWith("com.uber")||p.contains("ubercab"))h.postDelayed(()->scan(false),500);}private void scan(boolean refresh){AccessibilityNodeInfo r=getRootInActiveWindow();if(r==null||r.getPackageName()==null)return;String p=r.getPackageName().toString().toLowerCase(Locale.US);if(!(p.equals("com.ubercab.driver")||p.startsWith("com.uber")||p.contains("ubercab")))return;List<String> a=new ArrayList<>();collect(r,a);StringBuilder s=new StringBuilder();boolean relevant=false;for(String x:a){String l=x.toLowerCase(Locale.US);if(l.contains("opportun")||l.contains("reservation")||l.contains("airport")||l.contains("flight")||l.contains("yyz")||l.contains("boost")||l.contains("quest")||l.contains("promo")){relevant=true;s.append(x.trim()).append('\n');}}String sig=s.toString().trim();if(!sig.isEmpty()){if(!last.isEmpty()&&!sig.equals(last))AlertHelper.notify(this,"NEW UBER OPPORTUNITY","The Uber Opportunities screen changed. Open Uber Driver to check it.");last=sig;}if(refresh&&relevant)pull();}private void collect(AccessibilityNodeInfo n,List<String> o){if(n==null||o.size()>150)return;if(n.getText()!=null)o.add(n.getText().toString());if(n.getContentDescription()!=null)o.add(n.getContentDescription().toString());for(int i=0;i<n.getChildCount();i++)collect(n.getChild(i),o);}private void pull(){Path p=new Path();p.moveTo(540,500);p.lineTo(540,1400);dispatchGesture(new GestureDescription.Builder().addStroke(new GestureDescription.StrokeDescription(p,0,600)).build(),null,null);}public void onInterrupt(){}public void onDestroy(){h.removeCallbacksAndMessages(null);super.onDestroy();}}
